// Build with: c++ -std=c++14 -Isrc tests_pytest/generate_spin_md_layouts.cpp -o /path/to/generator
// Redirect stdout to src/force/nep_spin/spin_md_layouts.cuh.
#include "main_nep/nep_spin/spin_compile.cuh"
#include <iostream>
int main() {
  std::cout << "/* This file is part of GPUMD. SPDX-License-Identifier: LGPL-3.0-or-later */\n"
               "// Generated by tests_pytest/generate_spin_md_layouts.cpp.\n"
               "#pragma once\n#include \"spin_layout.cuh\"\n";
  for (int soc = 0; soc <= 1; ++soc) {
    std::string text = nep_spin::compile_layout(nep_spin::Layout(3, 2, 2, soc));
    const std::string name = "CompiledLayout";
    text.replace(text.find(name), name.size(), soc ? "MDLayoutSOC" : "MDLayoutNoSOC");
    for (const std::string key : {"tile", "edge_cached"}) {
      const std::string from = "enum : int { " + key + " = ";
      const auto a = text.find(from) + from.size();
      const auto b = text.find(" }", a);
      text.replace(a, b-a, key == "tile" ? "Tile" : "EdgeCached");
    }
    text.replace(text.find("struct MDLayout"), 0, "template<int Tile = 1, bool EdgeCached = false> ");
    std::cout << text;
  }
}
